        vm.deal(actor, sendAmt);

        // perform the Put as the fuzzed actor
        vm.prank(actor);
        // call Put with fuzzed unlockTime and fuzzed (bounded) ether value
        try c.Put{value: sendAmt}(unlockTime) {
            // success
        } catch {
            // If Put reverts for some inputs, the reference and mutant would both revert similarly here
            // still we proceed to check the property only when call completed
        }

        // Exactly one assertion: in the reference, after Put completes, Acc[actor].unlockTime >= block.timestamp
        // Read via public getter Acc(actor).unlockTime (auto-generated struct getter returns tuple)
        // The getter returns (uint256 unlockTime, uint256 balance)
        (uint256 storedUnlockTime, uint256 storedBalance) = c.Acc(actor);
        // The property: storedUnlockTime >= block.timestamp OR storedBalance == 0 (if Put reverted/was a no-op and no funds)
