pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 unlockTime, uint256 give) public {
        // keep give within reasonable bounds and allow 0 value too
        give = bound(give, 0, 10 ether);
        // actor must be non-zero
        vm.assume(actor != address(0));

        // fund actor so they can send value
        vm.deal(actor, give + 1 ether);

        // perform Put as actor sending `give` and _unlockTime
        vm.prank(actor);
        bool ok;
        try c.Put{value: give}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract guarantees that after a Put call completes (succeeds),
        // Acc[actor].unlockTime >= block.timestamp. We assert that when the call did not revert,
        // the stored unlockTime is >= block.timestamp. This holds for the reference and is
        // violated by the mutant that blindly assigns _unlockTime (some fuzzed unlockTime < now).
        if (ok) {
            uint stored = c.Acc(actor).unlockTime;
            assertTrue(stored >= block.timestamp);
        } else {
            // If the Put reverted, we cannot make an invariant claim about state; in that case
            // assert that the call indeed reverted (ok == false) is already reflected by branch.
            // Still assert true to have single assert in all branches by checking ok == false || ...
            assertTrue(!ok || c.Acc(actor).unlockTime >= block.timestamp);
        }
    }
}

