import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: caller address and a proposed new unlockTime, plus an amount to send
    function testFuzz_property(address caller, uint256 newUnlockTime, uint256 amount) public {
        // keep caller non-zero and amount small enough to deal with
        vm.assume(caller != address(0));
        amount = bound(amount, 0, 5 ether);

        // Ensure caller has funds
        vm.deal(caller, amount);

        // First, have caller call Put with some initial unlock time in the future to establish a baseline
        uint256 baselineTime = block.timestamp + 1 hours;
        vm.prank(caller);
        if (amount > 0) {
            c.Put{value: amount}(baselineTime);
        } else {
            // If amount is zero, still call to set unlockTime (Put allows zero-value calls)
            c.Put{value: 0}(baselineTime);
        }

        // Read stored unlockTime after first Put
        uint256 storedBefore = c.Acc(caller).unlockTime;

        // Now call Put again with the fuzzed newUnlockTime and possibly some value
        // Use a possibly different value but keep caller funded
        uint256 sendValue = amount > 0 ? amount : 0;
        vm.prank(caller);
        try c.Put{value: sendValue}(newUnlockTime) {
            // call succeeded
        } catch {
            // If it reverts, treat as non-violation for monotonicity (we only assert on stored value)
        }

        // Exactly one assertion: in the correct contract, stored unlockTime never decreases as a result of Put
        uint256 storedAfter = c.Acc(caller).unlockTime;
        assertTrue(storedAfter >= storedBefore);
    }
}

