import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: actor and amount and unlockTime
    function testFuzz_property(address actor, uint256 amount, uint256 _unlockTime) public {
        // Keep domain wide but meaningful: nonzero value and avoid excessive gas by bounding amount
        amount = bound(amount, 1, 5 ether);
        // actor should not be zero address
        vm.assume(actor != address(0));

        // Deploy an attacker contract that will call back into c during LogFile.AddMessage if it receives funds.
        // The reference C's ordering and nonReentrant_ prevents reentrancy messing with balance accounting.
        attacker = new Attacker(c);

        // Fund the attacker so it can send msg.value when it calls Put on c
        vm.deal(actor, amount);

        // Make the attacker the caller who calls Put on c, but route LogFile to call attacker by setting LogFile to attacker
        // We cannot change c.LogFile after deployment; however, c was constructed with address(this) as LogFile.
        // The AddMessage will push to LogFile (which is address(this)), so to trigger reentrancy we need the AddMessage to call external code.
        // Instead, we simulate reentrancy by having the attacker be the caller and during Put's external interactions (if any)
        // the attacker will attempt to reenter. To cause an external call in Put we need LogFile.AddMessage to be an external call.
        // Since c.LogFile points to this test contract (address(this)), we implement a fallback that forwards to attacker to cause reentrancy.

        // Arrange: ensure this contract has code at runtime that reenters c when AddMessage is invoked.
        // We'll call c.Put from actor. When c.AddMessage calls LogFile.AddMessage (i.e., this contract), the call will hit
        // the onAddMessage function below which will forward reentrant call to c via attacker.

        // Give this contract some balance so c's AddMessage can call here
        vm.deal(address(this), 1 ether);

        // Record old balance from the mapping before the call
        uint256 oldBalance = c.Acc(actor).balance;

        // Have actor call Put on c with fuzzed unlockTime and value
        vm.prank(actor);
        c.Put{value: amount}(_unlockTime);

        // After Put completes, the invariant (reference) is: Acc[actor].balance == oldBalance + amount
        uint256 newBalance = c.Acc(actor).balance;

        // Single assertion: reference satisfies this for all inputs; mutant (reentrancy ordering change) can violate it
        assertTrue(newBalance == oldBalance + amount);
    }

    // This fallback will be invoked when c.LogFile.AddMessage is called (LogFile was set to address(this) in setUp())
    // We implement AddMessage so that during the external call from c we attempt a reentrant call into c via an attacker helper.
    // The attacker contract will try to call c.Put with zero value (reentrancy attempt) to observe ordering effects.
    // Note: function signature must match: AddMessage(address,uint,string)
    function AddMessage(address _adr, uint _val, string memory _data) public {
        // During AddMessage (an external call from c), attempt a reentrant call into c via attacker
        // We do this with low-level call from this contract to mimic an external party calling back.
        // To avoid revert risk, wrap in try/catch on the external call to attacker which will perform the reentrant call.
        try attacker.attack() {
            // ignore result
        } catch {
            // ignore failures
        }
